_A5 = [("Malungkot kami kapag wala si nanay.", "kapag", "when", "We are sad when Mother is not here."), ("Gumising ako bago ka umalis ng bahay.", "bago", "before", "I woke up before you left the house."), ("Kumanan ka para makarating ka sa bangko.", "para", "so that, in order that", "Turn right so that you reach the bank."), ("Kumaliwa ka bago ka makarating sa kanto.", "bago", "before", "Turn left before you reach the corner."), ("Pumarada ka kapag nakita mo ang gusali.", "kapag", "when", "Park when you see the building."), ("Bago ka lumiko, tumingin ka sa kanan.", "bago", "before", "Before you turn, look to the right."), ("Napakahirap ng liksiyon kaya nag-aaral kami nang mabuti.", "kaya", "that’s why", "The lesson is very hard, that’s why we study well."), ("Manonood ako ng sine kapag kasama ka.", "kapag", "when", "I will watch a movie when you are with me.")]
