_C8 = [("Sandra", "Stella, mag-relax tayo! Lagi ka na lang nagtatrabaho.", "Stella, let’s relax! You are always working."), ("Stella", "’Mareng Sandra, wala akong oras. Dalawa ang trabaho ko. Wala akong pahinga! Nag-aalmusal nga ako habang nagluluto at naglilinis ng bahay, e.", "Comadre Sandra, I have no time. I have two jobs. I have no rest! I even eat breakfast while cooking and cleaning the house."), ("Sandra", "’Mare, ako rin dala-dalawa ang trabaho ko. Nag-aalaga pa ako ng mga anak ko. Pero kailangan rin nating magpahinga at mag-relax paminsan-minsan.", "Comadre, I too have two jobs each. I also take care of my children. But we also need to rest and relax once in a while."), ("Stella", "Sige na nga, day off naman ngayon.", "All right then, it’s a day off today anyway.")]
