_A10 = [("Gumigising ako nang alas-singko y medya tuwing umaga.", "I wake up at 5:30 every morning."), ("Naghihilamos, nagsisipilyo, at nagbibihis ako.", "I wash my face, brush my teeth and dress."), ("May mga araw na nag-jo-jogging kami bago magklase. Kapag ganun, naliligo ako pagkatapos.", "On some days we jog before class. When that happens, I shower afterwards."), ("Nag-aalmusal ako nang bandang alas-siyete sa Chow Hall o bumibili ng pagkain sa kapiterya.", "I have breakfast at around seven at the Chow Hall or buy food at the cafeteria."), ("Pumapasok ako sa eskuwelahan nang alas-siyete y medya. Nagbubus ako papuntang klase.", "I go to school at seven-thirty. I take the bus to class."), ("Nag-aaral kami nang anim na oras araw-araw, umpisa ng alas-siyete singkuwenta y singko nang umaga.", "We study for six hours every day, starting at 7:55 in the morning."), ("Natatapos ang klase sa umaga nang alas-diyes kuwarenta y singko.", "The morning class ends at 10:45."), ("Tapos, nanananghalian ako. Umuuwi ako ng baraks nang alas-tres n.h.", "Then I have lunch. I go home to the barracks at three p.m."), ("Sa hapon, pagkatapos ng klase, kadalasan, nagpapahinga ako.", "In the afternoon, after class, I usually rest."), ("Minsan, naglilinis ako ng kuwarto ko. Minsan naman, nagsasanay-pisikal.", "Sometimes I clean my room. Other times I do physical training."), ("Naghahapunan ako bago mag-alas-sais n.g.", "I have supper before six p.m."), ("Paminsan-minsan, nanonood ako ng TV o naglalaro ng video games. Alas-diyes natutulog na ako.", "Once in a while I watch TV or play video games. At ten I am already asleep.")]
