_S12 = [("You", "Kumusta na ang pag-aaral at pagsasanay mo?", "How are your studies and training going?"), ("Friend", "Mahirap ang mag-aral habang nagsasanay pisikal.", "It’s tough to study while doing physical training."), ("You", "Kakayanin mo iyan. Ano ang ginagawa mo sa mga araw na may pasok?", "You will manage. What do you do on weekdays?"), ("Friend", "Gumigising ako nang maaga, mga alas-kuwatro y medya. Nagsasanay pisikal ako at bumabalik sa barracks. Tapos naliligo, kumakain at nagbibihis para sa klase.", "I wake up early, at around 4:30. I do physical training and return to the barracks. Then I take a shower, eat and dress for class."), ("You", "Gaano kalayo ang barracks sa paaralan mo?", "How far is the barracks from your school?"), ("Friend", "Medyo malayo, mga isang milya. Madalas nagbubus ako o tumatakbo na lang.", "A bit far, about a mile. I often take the bus or just run.")]
_S13 = [("A", "Kumusta! Ano ang regular na gawain mo sa DLI?", "Hello! What is your regular routine at DLI?"), ("B", "Medyo mahirap ang mag-aral habang nagsasanay pisikal araw-araw. Gumigising ako nang alas-singko. Ang pisikal na pagsasanay ay nang alas-sais.", "It’s a little hard to study while doing physical training every day. I wake up at five. The physical training is at six."), ("A", "Iba ang iskedyul ko at mas madali kaysa sa iyo. Pagkagising ko, nagsisipilyo ako, naliligo at nag-aalmusal.", "My schedule is different and easier than yours. After waking up, I brush my teeth, shower and have breakfast."), ("B", "Mas maganda at mas madali ang iskedyul mo kaysa sa akin. Anong oras ka gumigising?", "Your schedule is better and easier than mine. What time do you wake up?")]
_GL = [("alimango", "crab"), ("baboy damo", "wild boar"), ("bakasyon", "vacation"), ("balde", "pail"), ("barkada", "a group of friends"), ("baryo", "barrio"), ("bulaklak", "flowers"), ("dalampasigan", "seashore"), ("gumagawa", "doing"), ("gumigising", "waking up"), ("hipon", "shrimp"), ("humawak", "touch, hold"), ("ilog", "river"), ("ipagsabay", "to do at the same time"), ("iskul", "school"), ("kabibi", "empty clamshell"), ("karatig", "neighboring"), ("kasama", "with"), ("kawawa", "pitiful"), ("kuweba", "cave"), ("lawa", "lake"), ("ligaw na bulaklak", "wild flowers"), ("mag-ayos", "fix"), ("magkuwento", "tell a story"), ("magpahinga", "rest"), ("magsuklay", "comb"), ("mahirap", "difficult"), ("makatipid", "to save money"), ("malungkot", "lonely"), ("nag-aalmusal", "having breakfast"), ("nag-aaral", "studying"), ("nagbabaon", "bringing own food (to school)"), ("nagbibihis", "putting on clothes"), ("nagdadasal", "praying"), ("naghihilamos", "washing the face"), ("naglalaan", "setting aside, allocating"), ("naglalaba", "doing the laundry, washing clothes"), ("nagluluto", "cooking"), ("nagsisipilyo", "brushing the teeth"), ("nakakabagot", "boring"), ("naliligo", "taking a shower"), ("namamangka", "boating"), ("namamasyal", "strolling"), ("namimingwit", "fishing with hook and line"), ("namimitas", "picking"), ("namumulot", "gather"), ("nananahi", "sewing"), ("nanananghalian", "eating lunch, taking lunch"), ("nangangalap", "recruiting, enlisting new members"), ("nangangaso", "hunting"), ("nanghaharana", "serenading"), ("nanghihiram", "borrowing"), ("nanghuhuli", "catching"), ("napakahirap", "very difficult"), ("naranasan", "experienced"), ("pag-aaral", "studies"), ("pagkagising", "right after waking up"), ("palanggana", "basin"), ("paminsan-minsan", "sometimes"), ("parang", "meadows"), ("pisikal na pagsasanay", "physical training"), ("probinsiya", "province"), ("pulo", "island"), ("simbahan", "church"), ("sirang damit", "torn clothes"), ("sumasama", "joining"), ("tumatakbo", "running")]
_VS = [("Gumagawa siya ng kanyang asignatura.", "He is doing his assignment."), ("Gumigising ang mga sundalo ng maagang-maaga.", "The soldiers wake up very early."), ("Humawak ka baka ka mahulog.", "Hold on or you might fall."), ("Mag-ayos ka naman nang konti, magsisimba tayo.", "Please fix yourself up a bit, we are going to church."), ("Magkuwento ka naman tungkol sa bakasyon mo sa Pilipinas.", "Please tell me about your vacation in the Philippines."), ("Gusto kong magpahinga.", "I want to rest."), ("Ayos na ang buhok mo, huwag ka nang magsuklay.", "Your hair is fine, don’t comb it anymore."), ("Mahirap ang buhay nila pero natapos niya ang kanyang pag-aaral.", "Their life is hard but he finished his studies."), ("Hindi siya makatipid kasi gala siya nang gala.", "He can’t save money because he keeps going out."), ("Lagi ka bang nag-aalmusal sa cafeteria?", "Do you always have breakfast in the cafeteria?"), ("Ang sipag-sipag mo naman, lagi kang nag-aaral.", "You are so diligent, you always study."), ("Nagtitipid ako kaya nagbabaon ako araw-araw.", "I am saving money so I bring my own lunch every day."), ("Nagbibihis ako ng maayos tuwing nagsisimba.", "I dress properly whenever I go to church."), ("Nagdadasal kami ng pamilya ko gabi-gabi.", "My family and I pray every night."), ("Naghihilamos ako pagkagising ko sa umaga.", "I wash my face right after waking up in the morning."), ("Naglalaan ako ng oras sa mga anak ko tuwing Sabado’t Linggo.", "I set aside time for my children on Saturdays and Sundays."), ("Naglalaba ako tuwing Biyernes ng gabi.", "I do the laundry every Friday night."), ("Nagluluto rin ba ang nanay mo tuwing pumupunta siya dito sa dorm?", "Does your mother also cook whenever she comes here to the dorm?"), ("Nagsisipilyo ako pagkakain ko araw-araw.", "I brush my teeth after eating every day."), ("Hindi ba nakakabagot ang mag-aral ng wikang Tagalog?", "Isn’t it boring to study the Tagalog language?"), ("Naliligo ka ba sa gabi bago matulog?", "Do you take a shower at night before sleeping?"), ("Tuwing Sabado namamangka kami ng mga pinsan ko.", "Every Saturday my cousins and I go boating."), ("Namamasyal kami ng mga Tita at Tito ko sa Luneta tuwing Linggo.", "My aunts and uncles and I stroll in Luneta every Sunday."), ("Kasama kong namimingwit tuwing Sabado ang mga pamangkin ko.", "My nieces and nephews fish with me every Saturday."), ("Namimitas kami ng mga ligaw na bulaklak ng mga pinsan kong babae sa parang.", "My girl cousins and I pick wild flowers in the meadow."), ("Namumulot kami ng mga kabibe sa dalampasigan tuwing hapon.", "We gather shells on the seashore every afternoon."), ("Nananahi ka rin ba tulad ng ate mo?", "Do you also sew like your older sister?"), ("Sabay-sabay kami ng pamilya kong nanananghalian tuwing Linggo pagkatapos magsimba.", "My family and I have lunch together every Sunday after church."), ("Nangangalap sila ng mga bagong sundalong sasapi sa hukbo.", "They are recruiting new soldiers to join the army."), ("Nangangaso ka rin ba tulad ng amain mo?", "Do you also hunt like your uncle?"), ("Paminsan-minsan nanghaharana kami ng mga kaibigan ko.", "Once in a while my friends and I serenade."), ("Nanghihiram lang ako ng libro sa kaklase ko.", "I am just borrowing a book from my classmate."), ("Nanghuhuli ka rin ba ng alimango tulad ng bayaw mo?", "Do you also catch crabs like your brother-in-law?"), ("Naranasan mo na bang mamulot ng kabibe?", "Have you ever experienced gathering shells?"), ("Tumatakbo ako ng mga dalawang milya tuwing umaga.", "I run about two miles every morning.")]
