        + [M("What is tough for the friend at DLI?", "studying while doing physical training", ["finding food", "getting up late", "learning English"], "mahirap."), M("When does the friend wake up?", "around 4:30", ["around 7:00", "around noon", "around 9:00"], "alas-kuwatro y medya."), M("How far is the school from the barracks?", "about a mile", ["about ten miles", "next door", "about a meter"], "isang milya."), M("How does the friend get to school?", "by bus or by running", ["by taxi", "by plane", "by bicycle"], "nagbubus o tumatakbo."), M("What does B say about A’s schedule in Activity 13?", "it is better and easier", ["it is harder", "it is the same", "it is boring"], "mas madali."), M("What does mag-ayos mean?", "fix, groom", ["rest", "comb", "cook"], "mag-ayos."), M("What does magsuklay mean?", "comb", ["wash", "cook", "sew"], "magsuklay."), M("What does naglalaan mean?", "setting aside", ["running", "boating", "sewing"], "naglalaan."), M("What does nangangalap mean?", "recruiting", ["hunting", "serenading", "borrowing"], "nangangalap."), M("What does nananahi mean?", "sewing", ["fishing", "hunting", "boating"], "nananahi."), M("What does nanghuhuli mean?", "catching", ["picking", "gathering", "sewing"], "nanghuhuli."), M("What does tumatakbo mean?", "running", ["walking", "praying", "resting"], "tumatakbo.")]
        + [F("Gumigising ang mga sundalo ng ___. (very early)", "maagang-maaga", ["gabing-gabi", "tanghaling-tapat"], "maagang-maaga."), F("Hindi siya makatipid kasi gala siya nang ___. (go out)", "gala", ["luto", "bihis"], "gala nang gala."), F("Namamasyal kami sa ___ tuwing Linggo. (Luneta)", "Luneta", ["dalampasigan", "kuweba"], "Luneta."), F("Nagdadasal kami ng pamilya ko ___. (every night)", "gabi-gabi", ["araw-araw", "Linggu-linggo"], "gabi-gabi.")]
